function user(array $d):?array{foreach($d['users'] as $u)if(($u['id']??'')===($_SESSION['uid']??''))return $u;return null;}
function seasonKey(array $d):string{$s=mb_strtolower((string)($d['season']??'Питание'));return str_contains($s,'восстанов')?'recovery':(str_contains($s,'движ')?'movement':'nutrition');}
function habits(array $d,string $id,?string $season=null):array{$season=$season??seasonKey($d);$catalog=['nutrition'=>['Есть больше овощей и фруктов','Поддерживать водный баланс','Собирать сбалансированную тарелку','Есть больше домашней еды','Выстроить комфортный режим питания','Сократить то, чего хочется есть меньше','Есть осознанно','Разнообразить питание','Поддерживать организм питанием','Разобраться со своим питанием','Своя цель'],'recovery'=>['Достаточно спать','Выстроить режим сна','Устраивать digital sunset','Создать вечерний ритуал восстановления','Учиться расслабляться в течение дня','Добавить больше движения и свежего воздуха','Регулярно бывать на природе','Учиться отключаться от работы','Планировать личное восстановление','Своя цель'],'movement'=>['Больше двигаться в течение дня','Не засиживаться на работе','Добавить ежедневную разминку','Развивать силу','Развивать гибкость и мобильность','Заботиться о спине и осанке','Добавлять интенсивную нагрузку','Выбрать свой вид спорта','Поставить спортивную цель','Найти свой формат активного отдыха','Своя цель']];$answers=$d['questionnaires'][$id]['answers']??[];$goals=$answers['goals'][$season]??[];$out=[];foreach($goals as $i){$i=(int)$i;$name=$catalog[$season][$i-1]??null;if(!$name)continue;if($i===count($catalog[$season]))$name=trim((string)($answers['custom_goals'][$season]??''))?:$name;$out[]=['id'=>(string)$i,'name'=>$name];}if(!$out){foreach($d['users'] as $u)if($u['id']===$id){$out[]=['id'=>'legacy','name'=>$u['goal']?:'Ежедневная привычка'];break;}}return $out;}
function seasonChecks(array $d,string $id,?string $season=null):array{$season=$season??seasonKey($d);$h=habits($d,$id,$season);$first=$h[0]['id']??'legacy';return array_values(array_filter($d['checks']??[],fn($x)=>($x['user']??'')===$id&&(($x['season']??$season)===$season)&&in_array((string)($x['habit']??$first),array_column($h,'id'),true)));}
function successfulDays(array $d,string $id):int{$by=[];foreach(seasonChecks($d,$id) as $x)if(!empty($x['done']))$by[$x['date']]=true;return min(21,count($by));}
function progress(array $d,string $id):int{$h=habits($d,$id);$count=count($h);if(!$count)return 0;$done=count(array_filter(seasonChecks($d,$id),fn($x)=>!empty($x['done'])));return min(100,(int)round($done/(21*$count)*100));}
function achievements(array $d,string $id):array{$n=successfulDays($d,$id);$out=[];foreach([1=>'🌱',7=>'⚡',10=>'🎯',14=>'📅',21=>'🏆'] as $days=>$emoji)$out[]=['days'=>$days,'emoji'=>$emoji,'unlocked'=>$n>=$days];return $out;}
function teamProgress(array $d,string $team):int{$members=array_values(array_filter($d['users'],fn($u)=>($u['team']??'')===$team&&$u['role']!=='admin'));if(!$members)return 0;return (int)round(array_sum(array_map(fn($u)=>progress($d,$u['id'])>=50?progress($d,$u['id']):0,$members))/count($members));}
function questionnaireConfig(array $d):array{return array_merge(['closes_at'=>null,'assignment_finalized'=>false],$d['questionnaire_config']??[]);}
function questionnaireStatus(array $d,array $u):array{$q=$d['questionnaires'][$u['id']]??null;$cfg=questionnaireConfig($d);$now=time();$global=!empty($cfg['closes_at'])&&strtotime($cfg['closes_at'])<=$now;$expired=$q&&$now>=strtotime($q['submitted_at'])+72*3600;return ['completed'=>(bool)$q,'submitted_at'=>$q['submitted_at']??null,'answers'=>$q['answers']??null,'can_edit'=>!$global&&!$expired,'globally_closed'=>$global,'edit_deadline'=>$q?date(DATE_ATOM,strtotime($q['submitted_at'])+72*3600):null];}
function goalSets(array $d,string $id):array{$a=$d['questionnaires'][$id]['answers']['goals']??[];return array_map(fn($k)=>array_values(array_unique(array_map('strval',$a[$k]??[]))),['nutrition','recovery','movement']);}
function similarity(array $a,array $b):float{$v=0;for($k=0;$k<3;$k++){$intersection=count(array_intersect($a[$k],$b[$k]));$union=count(array_unique(array_merge($a[$k],$b[$k])));$v+=$union?$intersection/$union:0;}return $v/3;}
function distributionMembers(array $d):array{$out=[];foreach($d['users'] as $u){$id=$u['id'];if(($u['role']??'')==='admin'||($u['participating']??true)===false||empty($d['questionnaires'][$id]))continue;$sets=goalSets($d,$id);if(count(array_filter($sets,fn($x)=>count($x)>0))!==3)continue;$out[]=(string)$id;}sort($out,SORT_STRING);return $out;}
function distributionStats(array $d,array $groups):array{$sets=[];foreach($groups as $g)foreach($g as $id)$sets[$id]=goalSets($d,$id);$result=[];foreach($groups as $i=>$g){$sum=0;$pairs=0;$counts=[[],[],[]];$ach=0;foreach($g as $id){foreach($sets[$id] as $k=>$goals)foreach($goals as $v)$counts[$k][$v]=($counts[$k][$v]??0)+1;if(!empty($d['questionnaires'][$id]['answers']['achievement_categories'])||trim((string)($d['questionnaires'][$id]['answers']['achievement_description']??''))!=='')$ach++;}for($a=0;$a<count($g);$a++)for($b=$a+1;$b<count($g);$b++){$sum+=similarity($sets[$g[$a]],$sets[$g[$b]]);$pairs++;}foreach($counts as &$c){arsort($c,SORT_NUMERIC);$c=array_slice($c,0,3,true);}unset($c);$result[]=['team_id'=>$i+1,'member_ids'=>$g,'average_goal_similarity'=>$pairs?$sum/$pairs:0,'popular_goals'=>$counts,'achievements_count'=>$ach];}return $result;}
function buildDistribution(array $d,int $teamCount=10):array{$ids=distributionMembers($d);$n=count($ids);if(!in_array($teamCount,[2,10],true))throw new RuntimeException('Выберите 2 или 10 команд');if($n<$teamCount)throw new RuntimeException('Для '.$teamCount.' команд требуется минимум '.$teamCount.' участников с корректными анкетами. Сейчас: '.$n);$sets=[];foreach($ids as $id)$sets[$id]=goalSets($d,$id);$sim=[];foreach($ids as $a)foreach($ids as $b)if(strcmp($a,$b)<0)$sim[$a][$b]=similarity($sets[$a],$sets[$b]);$score=function($a,$b)use(&$sim){return strcmp($a,$b)<0?($sim[$a][$b]??0):($sim[$b][$a]??0);};$capacities=array_fill(0,$teamCount,intdiv($n,$teamCount));for($i=0;$i<$n%$teamCount;$i++)$capacities[$i]++;$groups=array_fill(0,$teamCount,[]);foreach($ids as $i=>$id)$groups[$i%$teamCount][]=$id;
