for($iteration=0;$iteration<100;$iteration++){$gain=0;$swap=null;for($a=0;$a<$teamCount;$a++)for($b=$a+1;$b<$teamCount;$b++)foreach($groups[$a] as $ia=>$x)foreach($groups[$b] as $ib=>$y){$delta=0;foreach($groups[$a] as $z)if($z!==$x)$delta+=$score($y,$z)-$score($x,$z);foreach($groups[$b] as $z)if($z!==$y)$delta+=$score($x,$z)-$score($y,$z);if($delta>$gain+0.00000001){$gain=$delta;$swap=[$a,$ia,$b,$ib];}}if(!$swap)break;[$a,$ia,$b,$ib]=$swap;[$groups[$a][$ia],$groups[$b][$ib]]=[$groups[$b][$ib],$groups[$a][$ia]];}
foreach($groups as &$g)sort($g,SORT_STRING);unset($g);return ['distribution_id'=>1,'status'=>'draft','team_count'=>$teamCount,'algorithm_version'=>'1.1','created_at'=>date(DATE_ATOM),'approved_at'=>null,'source_signature'=>distributionSignature($d),'teams'=>distributionStats($d,$groups)];}
function distributionSignature(array $d):string{$records=[];foreach(distributionMembers($d) as $id)$records[$id]=[$d['questionnaires'][$id]['updated_at']??'',$d['questionnaires'][$id]['answers']['goals']??[]];return hash('sha256',json_encode($records));}
function distributionView(array $d):array{$dist=$d['distribution']??null;if(!$dist)return ['status'=>'not_started','stale'=>false,'teams'=>[]];$groups=array_map(fn($x)=>$x['member_ids'],$dist['teams']);$dist['teams']=distributionStats($d,$groups);$dist['stale']=$dist['status']==='draft'&&($dist['source_signature']??'')!==distributionSignature($d);return $dist;}
function view(array $d):array{$u=user($d);$teams=[];foreach(($u['role']==='admin'||($d['distribution']['status']??'')==='approved')?$d['teams']:[] as $t)$teams[]=['name'=>$t,'progress'=>teamProgress($d,$t)];usort($teams,fn($a,$b)=>$b['progress']<=>$a['progress']);$people=array_map(function($x)use($d,$u){unset($x['password']);if($u['role']!=='admin'&&($d['distribution']['status']??'')!=='approved')$x['team']='';$x['progress']=progress($d,$x['id']);$x['achievements']=achievements($d,$x['id']);return $x;},$d['users']);$mine=array_values(array_filter($d['checks'],fn($x)=>$x['user']===$u['id']));$metrics=array_values(array_filter($d['metrics'],fn($x)=>$x['user']===$u['id']));return ['me'=>array_values(array_filter($people,fn($x)=>$x['id']===$u['id']))[0],'users'=>$people,'teams'=>$teams,'checks'=>$mine,'habits'=>habits($d,$u['id']),'successful_days'=>successfulDays($d,$u['id']),'bot_reminder'=>!count(array_filter($mine,fn($x)=>($x['date']??'')===date('Y-m-d')&&($x['season']??seasonKey($d))===seasonKey($d))) ,'metrics'=>$metrics,'experts'=>$d['experts'],'notices'=>$d['notices'],'season'=>$d['season'],'draw'=>$d['draw'],'questionnaire'=>questionnaireStatus($d,$u),'questionnaire_config'=>questionnaireConfig($d),'distribution'=>$u['role']==='admin'?distributionView($d):['status'=>$d['distribution']['status']??'not_started','team_id'=>$u['team']??''],'questionnaire_statuses'=>array_map(fn($x)=>['id'=>$x['id'],'completed'=>!empty($d['questionnaires'][$x['id']]),'date'=>$d['questionnaires'][$x['id']]['submitted_at']??null],$d['users'])];}
