elseif($action==='questionnaire_move'&&$me['role']==='admin'){$dist=$d['distribution']??null;if(!$dist||$dist['status']!=='draft')reply(['error'=>'Нет редактируемого черновика'],403);$id=(string)($input['id']??'');$target=(int)($input['team_id']??0);if($target<1||$target>count($dist['teams']))reply(['error'=>'Неверная команда'],422);$found=false;foreach($dist['teams'] as &$t){$idx=array_search($id,$t['member_ids'],true);if($idx!==false){array_splice($t['member_ids'],$idx,1);$found=true;}}unset($t);if(!$found)reply(['error'=>'Участник не найден'],404);$dist['teams'][$target-1]['member_ids'][]=$id;sort($dist['teams'][$target-1]['member_ids']);$d['distribution']=$dist;}
