elseif($action==='expert_admin'&&$me['role']==='admin'){$op=$input['operation']??'';$name=trim((string)($input['name']??''));$cat=$input['category']??'';$help=trim((string)($input['help']??''));$uid=(string)($input['user_id']??'');$basis=$input['basis']??'';if(!$name||mb_strlen($name)>120||!in_array($cat,['Питание','Движение','Восстановление'],true)||!$help||mb_strlen($help)>600||!in_array($basis,['','professional','personal'],true))reply(['error'=>'Проверьте данные эксперта'],422);if($uid&&!count(array_filter($d['users'],fn($u)=>$u['id']===$uid&&$u['role']!=='admin')))reply(['error'=>'Пользователь не найден'],422);$record=['name'=>$name,'category'=>$cat,'help'=>$help,'user_id'=>$uid,'basis'=>$basis,'competencies'=>mb_substr(trim((string)($input['competencies']??'')),0,600),'active'=>($input['active']??'1')!=='0'];if($op==='create'){$record['id']='expert-'.bin2hex(random_bytes(5));$d['experts'][]=$record;}elseif($op==='update'){$found=false;foreach($d['experts'] as &$x)if($x['id']===($input['id']??'')){$x=array_merge($x,$record);$found=true;}unset($x);if(!$found)reply(['error'=>'Эксперт не найден'],404);}else reply(['error'=>'Неизвестная операция'],422);}
elseif($action==='notice'&&$me['role']==='admin'){$text=trim($input['text']??'');if(!$text)reply(['error'=>'Введите текст'],422);array_unshift($d['notices'],['text'=>mb_substr($text,0,500),'date'=>date('d.m.Y')]);}
else reply(['error'=>'Недостаточно прав или неизвестная операция'],403);save($d);reply(view($d));}
